  Future<void> _enableAutoBackup() async {
    final String pathToSave = fileLocationController.text;
    final String passphrase = passphraseController.text;
    final String repeatPassphrase = passphraseRepeatController.text;

    if (validateFail(context, pathToSave, passphrase, repeatPassphrase)) return;

    if (mounted) {
      final now = DateTime.now();
      Exception? ex;
      final savedPath = await showLoading(
        whileFuture: () async {
          String adkString;
          int adkVersion;
          try {
            final adk = await compute(generateAdk, passphrase);
            adkString = Format.uint8listToString(adk.item2);
            adkVersion = adk.item1;
          } on Exception catch (e, s) {
            final String err = getErrorMessageFromSWBException(e);
            Logging.instance.e(err, error: e, stackTrace: s);
            rethrow;
          }

          await secureStore.write(key: "auto_adk_string", value: adkString);
          await secureStore.write(
            key: "auto_adk_version_string",
            value: adkVersion.toString(),
          );

          final fileToSavePath = createAutoBackupFilename(pathToSave, now);

          final backup = await SWB.createStackWalletJSON(
            secureStorage: secureStore,
          );

          final encryptedDataString = await SWB.encryptStackWalletWithADK(
            adkString,
            jsonEncode(backup),
            adkVersion,
          );

          await FS.writeStringToFile(
            encryptedDataString,
            pathToSave,
            fileToSavePath.split("/").last,
          );

          return fileToSavePath;
        }(),
        context: context,
        message: l10n.backupEncryptingInitial,
        subMessage: l10n.backupShouldntTakeLong,
        delay: const Duration(seconds: 1),
        onException: (e) => ex = e,
      );

      // showLoading has closed its progress dialog.
      if (mounted) {
        if (savedPath != null) {
          ref.read(prefsChangeNotifierProvider).autoBackupLocation = pathToSave;
          ref.read(prefsChangeNotifierProvider).lastAutoBackup = now;

          ref.read(prefsChangeNotifierProvider).isAutoBackupEnabled = true;

          await showDialog<dynamic>(
            context: context,
            barrierDismissible: false,
            builder: (context) {
              return DesktopDialog(
                maxHeight: double.infinity,
                maxWidth: 500,
                child: Padding(
                  padding: const EdgeInsets.only(
                    left: 32,
                    right: 32,
                    bottom: 32,
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        mainAxisAlignment: MainAxisAlignment.spaceBetween,
                        children: [
                          Text(
                            l10n.backupAutoEnabled(AppConfig.prefix),
                            style: STextStyles.desktopH3(context),
                          ),
                          const DesktopDialogCloseButton(),
                        ],
                      ),
                      const SizedBox(height: 40),
                      Row(
                        children: [
                          const Spacer(),
                          Expanded(
                            child: PrimaryButton(
                              label: l10n.commonOk,
                              buttonHeight: ButtonHeight.l,
                              onPressed: () {
                                Navigator.of(context).pop();
                              },
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              );
            },
          );
          if (mounted) {
            passphraseController.text = "";
            passphraseRepeatController.text = "";

            Navigator.of(context).pop();
          }
        } else {
          await showDialog<dynamic>(
            context: context,
            barrierDismissible: false,
            builder: (_) => StackOkDialog(
              title: l10n.backupEnableAutoFailed,
              message: ex?.toString(),
            ),
          );
        }
      }
    }
  }

